**Vulnerable Code Snippet:**

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class UserLogin {
    // Assume this method receives user input from a web form
    public void login(String username, String password) {
        Connection conn = null;  // Placeholder for actual connection setup
        try {
            conn = DriverManager.getConnection("jdbc:mysql://database_url", "username", "password");
            conn.createStatement();  // Vulnerable due to lack of prepared statements
            PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE username = '" + username + "' AND password = '" + password + "'");
            ps.executeQuery();
            // Potential SQL injection point here
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
